import { Cluster } from "ioredis"

/**
 * Atomic fixed-window counter: INCR the key, and if this is the
 * first hit in the window (count == 1), attach the window TTL.
 * Returns the post-increment count.
 */
const RATE_LIMIT_LUA = `
local current = redis.call("INCR", KEYS[1])
if tonumber(current) == 1 then
  redis.call("PEXPIRE", KEYS[1], ARGV[1])
end
return current
`

export type NotificationChannel = "push" | "email" | "sms"

export interface RateLimiterOptions {
  capacity: number
  windowMs: number
}

/**
 * Per-recipient rate limiter shared by the notification dispatcher.
 * Backed by the SAME Redis Cluster instance the send-queue workers use.
 */
export class RateLimiterService {
  private readonly redis: Cluster
  private readonly capacity: number
  private readonly windowMs: number

  constructor(redis: Cluster, options: RateLimiterOptions) {
    this.redis = redis
    this.capacity = options.capacity
    this.windowMs = options.windowMs
  }

  private buildKey(userId: string, channel: NotificationChannel): string {
    // One deterministic key per (user, channel) pair.
    return `rl:${userId}:${channel}`
  }

  /**
   * Returns true if the (userId, channel) pair is still under capacity
   * for the current window, and records this request against the count.
   */
  async allow(userId: string, channel: NotificationChannel): Promise<boolean> {
    const key = this.buildKey(userId, channel)

    const count = await this.redis.eval(
      RATE_LIMIT_LUA,
      1,
      key,
      this.windowMs,
    ) as number

    return count <= this.capacity
  }
}

export class NotificationDispatcher {
  constructor(private readonly limiter: RateLimiterService) {}

  async send(
    userId: string,
    channel: NotificationChannel,
    payload: unknown,
  ): Promise<{ sent: boolean; reason?: string }> {
    const admitted = await this.limiter.allow(userId, channel)

    if (!admitted) {
      return { sent: false, reason: "rate_limited" }
    }

    // ... enqueue payload onto the same Redis Cluster's send-queue ...
    return { sent: true }
  }
}
